#!/usr/bin/env bash
# fix_highlight.sh — Remove <w:highlightCs> from a .docx generated by docx-js.
#
# Background: docx-js incorrectly emits <w:highlightCs w:val="yellow"/> alongside
# the valid <w:highlight w:val="yellow"/> whenever highlight:'yellow' is set on
# a TextRun. <w:highlightCs> is not in the OOXML schema and causes validation
# failures in strict-mode readers (Word desktop on some versions, validators).
#
# This script:
#   1. Unpacks the .docx (it's a zip archive)
#   2. Strips all <w:highlightCs .../> elements from word/document.xml
#   3. Repacks into the original filename
#
# Usage:
#   bash fix_highlight.sh fastrBuild_NDA.docx
#   bash fix_highlight.sh fastrBuild_DSC_Custody_Agreement.docx

set -euo pipefail

DOCX="$1"

if [[ -z "$DOCX" ]]; then
  echo "Usage: $0 <filename.docx>"
  exit 1
fi

if [[ ! -f "$DOCX" ]]; then
  echo "Error: file not found: $DOCX"
  exit 1
fi

BASENAME="${DOCX%.docx}"
TMPDIR="${BASENAME}_tmp_fix"

echo "→ Unpacking $DOCX ..."
rm -rf "$TMPDIR"
mkdir -p "$TMPDIR"
unzip -q "$DOCX" -d "$TMPDIR"

echo "→ Stripping <w:highlightCs> ..."
# macOS sed requires -i '' ; Linux sed requires -i (no argument)
# This detects which we have:
if sed --version 2>/dev/null | grep -q GNU; then
  sed -i 's|<w:highlightCs w:val="[^"]*"/>||g' "$TMPDIR/word/document.xml"
else
  sed -i '' 's|<w:highlightCs w:val="[^"]*"/>||g' "$TMPDIR/word/document.xml"
fi

echo "→ Repacking ..."
rm -f "$DOCX"
(cd "$TMPDIR" && zip -qr "../${DOCX}" .)
rm -rf "$TMPDIR"

echo "✓ Done: $DOCX (highlightCs removed)"
